// A 32-bit FNV-1a hash over the hex trace_id string -> deterministic [0,1).
function hashRatio(traceId) {
  let h = 0x811c9dc5;
  for (let i = 0; i < traceId.length; i++) {
    h ^= traceId.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h / 0xffffffff;
}
// ParentBased(TraceIdRatioBased(p)): the root samples by trace_id hash; both
// services compute the SAME function, so they agree without coordination.
function sampled(traceId, p) { return hashRatio(traceId) < p; }

const P = 0.2;
let kept = 0, disagreements = 0;
for (let i = 0; i < 100000; i++) {
  const traceId = (i * 2654435761 >>> 0).toString(16).padStart(8, '0');
  const serviceA = sampled(traceId, P);
  const serviceB = sampled(traceId, P); // independent process, same function
  if (serviceA !== serviceB) disagreements++;
  if (serviceA) kept++;
}
console.log('disagreements=' + disagreements);
console.log('keptPct=' + (kept / 100000 * 100).toFixed(1));
